#!/usr/bin/env node
/**
 * Builds the upload bundle for the official plugins:
 *
 *   release-assets/plugins/
 *   ├─ UPLOAD.md                          (generated guide: one-command + manual SQL)
 *   ├─ meta.json                          (sha256/size/version, generated from the packed bytes)
 *   ├─ flat/<id>-<version>.kern           (human-named copies)
 *   └─ supabase-storage/<id>/<version>/plugin.kern   (exact bucket layout)
 *
 * Run after `bun run plugins:pack` (which verifies via `plugins:check`):
 *   bun run plugins:bundle
 *
 * Publishing itself happens in the kern-web repo:
 *   npm run publish:plugins -- ../kern/release-assets/plugins --update-meta
 */
import { cpSync, mkdirSync, readFileSync, rmSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const PLUGINS = ["minecraft_java", "discord_bot"];
const BUNDLE = join(ROOT, "release-assets", "plugins");

// Metadata comes from the sibling script so hash/size logic lives in one place.
const metaRun = spawnSync(
  process.execPath,
  [join(ROOT, "scripts", "plugin-registry-meta.mjs")],
  { encoding: "utf8" },
);
if (metaRun.status !== 0) {
  console.error(metaRun.stderr || "plugin-registry-meta failed");
  process.exit(1);
}
const meta = JSON.parse(metaRun.stdout);

for (const plugin of meta.plugins) {
  if (!existsSync(join(ROOT, "plugins", plugin.id, `${plugin.id}.kern`))) {
    console.error(`missing plugins/${plugin.id}/${plugin.id}.kern — run: bun run plugins:pack`);
    process.exit(1);
  }
}

rmSync(BUNDLE, { recursive: true, force: true });
mkdirSync(join(BUNDLE, "flat"), { recursive: true });
writeFileSync(join(BUNDLE, "meta.json"), JSON.stringify(meta, null, 2) + "\n");

const sqlBlocks = [];
const tableRows = [];

for (const plugin of meta.plugins) {
  const source = join(ROOT, "plugins", plugin.id, `${plugin.id}.kern`);
  const versioned = join(BUNDLE, "flat", `${plugin.id}-${plugin.version}.kern`);
  const storageDir = join(BUNDLE, "supabase-storage", plugin.id, plugin.version);
  mkdirSync(storageDir, { recursive: true });
  cpSync(source, versioned);
  cpSync(source, join(storageDir, "plugin.kern"));

  tableRows.push(
    `| ${plugin.id} | ${plugin.version} | ${plugin.size_bytes} | \`${plugin.sha256}\` |`,
  );
  sqlBlocks.push(`-- ${plugin.id} ${plugin.version}
delete from public.plugin_versions
where plugin_id = (select id from public.plugins where slug = '${plugin.id}')
  and version = '${plugin.version}';

insert into public.plugin_versions
  (plugin_id, version, kern_compat, storage_path, sha256, size_bytes, changelog)
select id, '${plugin.version}', '${plugin.kern_compat}',
       '${plugin.id}/${plugin.version}/plugin.kern',
       '${plugin.sha256}',
       ${plugin.size_bytes},
       'official ${plugin.version} release - see the kern repository release notes'
from public.plugins where slug = '${plugin.id}';`);
}

const uploadMd = `# official plugin upload bundle

Generated by \`bun run plugins:bundle\` (kern). Do not hand-edit — rerun the script.

| plugin | version | size | sha256 |
|---|---|---|---|
${tableRows.join("\n")}

## preferred: one command (kern-web)

\`\`\`bash
cd ../kern-web
npm run publish:plugins -- ../kern/release-assets/plugins --dry-run   # verify locally
npm run publish:plugins -- ../kern/release-assets/plugins --update-meta
\`\`\`

Needs \`NEXT_PUBLIC_SUPABASE_URL\` and \`SUPABASE_SERVICE_ROLE_KEY\` in
kern-web's \`.env.local\`. The script uploads to the \`plugin-kern\` bucket at
\`<id>/<version>/plugin.kern\`, replaces the \`plugin_versions\` row, and (with
\`--update-meta\`) refreshes the plugin page from the seed.

## manual: dashboard + SQL editor

1. Supabase → Storage → bucket \`plugin-kern\`: drag the contents of
   \`supabase-storage/\` (keeps \`<id>/<version>/plugin.kern\` paths intact).
2. SQL editor, run:

\`\`\`sql
${sqlBlocks.join("\n\n")}
\`\`\`

\`created_at\` defaults to now, and the registry treats the newest
\`created_at\` as the live version.

## verify

- \`https://kern.aaenz.no/api/download?id=<slug>&v=<version>\` → 302
- the plugin page shows the new version and the app offers the update with
  checksum verification.
`;

writeFileSync(join(BUNDLE, "UPLOAD.md"), uploadMd);

console.log(`packed bundle → ${BUNDLE}`);
for (const plugin of meta.plugins) {
  console.log(`  ${plugin.id}@${plugin.version}  ${plugin.size_bytes} B  sha256 ${plugin.sha256.slice(0, 12)}…`);
}
console.log("  UPLOAD.md + meta.json written");
